    /// } + WelcomeMessage 
    /// ')
    /// </summary>
    public string HomePage_Welcome() => DateTime.Now.Hour switch{>= 5 and < 12 => "早上好，",>= 12 and < 18 => "下午好，",>= 18 and < 22 => "傍晚好，",_ => "晚上好，",} + WelcomeMessage ;
    
