    string ISimpleLocalizerBase.HomePage_Welcome() => HomePage_Welcome();
    /// <summary>
    /// Get the localized string for HomePage_Welcome in ja-JP (like '
    /// DateTime.Now.Hour switch
    /// {
    /// &gt;= 5 and &lt; 12 =&gt; &quot;おはようございます、&quot;,
    /// &gt;= 12 and &lt; 18 =&gt; &quot;こんにちは、&quot;,
    /// &gt;= 18 and &lt; 22 =&gt; &quot;こんばんは、&quot;,
    /// _ =&gt; &quot;こんばんは、&quot;,
    /// } + WelcomeMessage
    /// ')
    /// </summary>
    /// <remarks>
    /// Time-based greeting expression translated to Japanese
    /// </remarks>
    public string HomePage_Welcome() => DateTime.Now.Hour switch{>= 5 and < 12 => "おはようございます、",>= 12 and < 18 => "こんにちは、",>= 18 and < 22 => "こんばんは、",_ => "こんばんは、",} + WelcomeMessage;
    
