    string ISimpleLocalizerBase.HomePage_Welcome() => HomePage_Welcome();
    /// <summary>
    /// Get the localized string for HomePage_Welcome in ko-KR (like '
    /// DateTime.Now.Hour switch
    /// {
    /// &gt;= 5 and &lt; 12 =&gt; &quot;좋은 아침,&quot;,
    /// &gt;= 12 and &lt; 18 =&gt; &quot;좋은 오후,&quot;,
    /// &gt;= 18 and &lt; 22 =&gt; &quot;좋은 저녁,&quot;,
    /// _ =&gt; &quot;안녕하세요,&quot;,
    /// } + WelcomeMessage
    /// ')
    /// </summary>
    /// <remarks>
    /// Time-based greeting expression using C# switch expression - maintains original code structure while localizing greeting phrases
    /// </remarks>
    public string HomePage_Welcome() => DateTime.Now.Hour switch{>= 5 and < 12 => "좋은 아침,",>= 12 and < 18 => "좋은 오후,",>= 18 and < 22 => "좋은 저녁,",_ => "안녕하세요,",} + WelcomeMessage;
    
