    string ISimpleLocalizerBase.HomePage_Welcome() => HomePage_Welcome();
    /// <summary>
    /// Get the localized string for HomePage_Welcome in de-DE (like '
    /// DateTime.Now.Hour switch
    /// {
    ///     &gt;= 5 and &lt; 12 =&gt; &quot;Guten Morgen, &quot;,
    ///     &gt;= 12 and &lt; 18 =&gt; &quot;Guten Tag, &quot;,
    ///     &gt;= 18 and &lt; 22 =&gt; &quot;Guten Abend, &quot;,
    ///     _ =&gt; &quot;Guten Abend, &quot;,
    /// } + WelcomeMessage
    /// ')
    /// </summary>
    public string HomePage_Welcome() => DateTime.Now.Hour switch{    >= 5 and < 12 => "Guten Morgen, ",    >= 12 and < 18 => "Guten Tag, ",    >= 18 and < 22 => "Guten Abend, ",    _ => "Guten Abend, ",} + WelcomeMessage;
    
