    string ISimpleLocalizerBase.HomePage_Welcome() => HomePage_Welcome();
    /// <summary>
    /// Get the localized string for HomePage_Welcome in pt-BR (like '
    /// DateTime.Now.Hour switch
    /// {
    ///     &gt;= 5 and &lt; 12 =&gt; &quot;Bom dia, &quot;,
    ///     &gt;= 12 and &lt; 18 =&gt; &quot;Boa tarde, &quot;,
    ///     &gt;= 18 and &lt; 22 =&gt; &quot;Boa noite, &quot;,
    ///     _ =&gt; &quot;Boa noite, &quot;,
    /// } + WelcomeMessage
    /// ')
    /// </summary>
    /// <remarks>
    /// Traduzidas as saudações em português brasileiro. &apos;Boa noite&apos; é usado tanto para o período da noite quanto da madrugada, conforme o uso comum no Brasil.
    /// </remarks>
    public string HomePage_Welcome() => DateTime.Now.Hour switch
{
    >= 5 and < 12 => "Bom dia, ",
    >= 12 and < 18 => "Boa tarde, ",
    >= 18 and < 22 => "Boa noite, ",
    _ => "Boa noite, ",
} + WelcomeMessage;
    
